-- demo listing photos (Wikimedia Commons, credited per photo)
/** @env development */


update listings l
   set coverPhoto = '/photos/' || p.id || '/' || p.hash
  from listingPhotos p
 where p.listingId = l.id and p.position = 0;

update conversations c set listingCover = l.coverPhoto from listings l where l.id = c.listingId;
